#!/usr/bin/env python3
"""Check that the repository numbers and the 112 figure package agree.

The script checks three layers:

* the canonical values transcribed in ``publication_figures.py`` against the
  112 manuscript tables and the Fig. 3 caption;
* the JSON artifacts generated by the benchmark, sweep, filtered comparison,
  Go1 repeats, and blocked cross-validation;
* the deliverables in ``112/`` (vector PDFs and 1000 dpi PNGs).

It also exercises Proposition 1 (monotone RW-MVK objective), Proposition 2
(exponential attenuation), the r = 0 depth boundary, and the order-of-magnitude
accounting behind the 38.5x / 97.4% covariance claims.
"""

from __future__ import annotations

import argparse
import json
import shutil
import subprocess
import sys
from pathlib import Path

import numpy as np
from PIL import Image

PROJECT_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(PROJECT_ROOT / "scripts"))

import publication_figures as pf  # noqa: E402
from ahpff import ReliabilityWeightedKMeans, modality_weights  # noqa: E402

FAILURES: list[str] = []
NOTES: list[str] = []


def check(name: str, condition: bool, detail: str = "") -> None:
    if condition:
        print(f"[PASS] {name}")
    else:
        FAILURES.append(f"{name}: {detail}")
        print(f"[FAIL] {name}  {detail}")


def close(value: float, expected: float, tolerance: float = 5e-4) -> bool:
    return abs(float(value) - float(expected)) <= tolerance


def load_json(relative: str) -> dict:
    path = PROJECT_ROOT / relative
    if not path.exists():
        raise SystemExit(f"Missing {path}")
    return json.loads(path.read_text(encoding="utf-8"))


def check_canonical_tables() -> None:
    check("Table 4: RA-AHPFF clean accuracy", pf.PAPER_CLEAN_ACC[-1] == 71.1)
    check("Table 4: RA-AHPFF severe accuracy", pf.PAPER_SEVERE_ACC[-1] == 60.0)
    check("Table 4: shuffled severe accuracy", pf.PAPER_SEVERE_ACC[-2] == 56.2)
    check("Table 4: severe ARI", pf.PAPER_SEVERE_ARI[-1] == 0.195)
    check("Table 4: vision silhouette paradox", pf.PAPER_SEVERE_SIL[0] == 0.432)
    check("Table 5: RA-AHPFF progressive row", pf.PAPER_ACC_LEVELS[-1] == (71.1, 60.4, 60.2, 60.0))
    check("Table 8: baseline visual weight", pf.WEIGHT_WV[0] == 0.425)
    check("Table 8: depth-dropout visual weight", pf.WEIGHT_WV[-1] == 0.724)
    check("Table 9: selected lambda", pf.LAMBDA_ACC[3] == 60.0)
    check("Table 9: selected over-clustering", pf.ROC_ACC[-1] == 77.8)


def check_figure_source_data() -> None:
    sweep = load_json("figures/reliability_sweep.json")
    vision = sweep["vision_sweep"]["levels"]
    depth = sweep["depth_sweep"]["levels"]
    check("Fig. 3: visual qv endpoint", close(vision[-1]["mean_qv"]["mean"], 0.323, 1e-3), str(vision[-1]["mean_qv"]["mean"]))
    check("Fig. 3: visual wv endpoint", close(vision[-1]["mean_wv"]["mean"], 0.100, 1e-3), str(vision[-1]["mean_wv"]["mean"]))
    check("Fig. 3: visual ACC endpoint", close(vision[-1]["acc"]["mean"] * 100.0, 64.7, 0.06), str(vision[-1]["acc"]["mean"] * 100.0))
    check("Fig. 3: depth qd endpoint", close(depth[-1]["mean_qd"]["mean"], 0.355, 1e-3), str(depth[-1]["mean_qd"]["mean"]))
    check("Fig. 3: depth wd endpoint", close(depth[-1]["mean_wd"]["mean"], 0.279, 1e-3), str(depth[-1]["mean_wd"]["mean"]))
    check("Fig. 3: depth ACC endpoint", close(depth[-1]["acc"]["mean"] * 100.0, 59.0, 0.06), str(depth[-1]["acc"]["mean"] * 100.0))

    sapf = load_json("figures/sapf_tracking_result.json")
    table10 = {
        "LO": 0.3456,
        "SPF": 0.2647,
        "LPF": 0.1107,
        "EKF": 0.1734,
        "SAPF-Pred": 0.1158,
        "SAPF-Oracle": 0.1123,
        "SAPF-Shuffled": 0.1374,
    }
    for method, expected in table10.items():
        value = sapf["aggregate"][method]["position_rmse"]["mean"]
        check(f"Table 10: {method} position RMSE", close(value, expected, 5e-4), f"{value:.4f} vs {expected:.4f}")

    repeats = load_json("figures/degradation_runs/summary.json")
    table11 = {
        "baseline": {"SPF": 0.1711, "LPF": 0.0883, "SAPF": 0.0877},
        "degraded": {"SPF": 0.1726, "LPF": 0.0937, "SAPF": 0.0958},
    }
    for condition, values in table11.items():
        for method, expected in values.items():
            value = repeats[condition]["metrics"][method]["position_rmse"]["mean"]
            check(f"Table 11: {condition} {method}", close(value, expected, 5e-4), f"{value:.4f} vs {expected:.4f}")
    check(
        "Table 11: closed-loop semantic accuracy",
        close(repeats["baseline"]["semantic_accuracy"]["mean"] * 100.0, 90.1, 0.05)
        and close(repeats["degraded"]["semantic_accuracy"]["mean"] * 100.0, 77.6, 0.05),
    )

    model = load_json("data/ahpff_go1_model.json")
    check("Table 6: blocked CV", close(model["blocked_cv_accuracy"] * 100.0, 77.8, 0.05), str(model["blocked_cv_accuracy"]))
    check("Table 6: random CV", close(model["random_cv_accuracy"] * 100.0, 91.2, 0.05), str(model["random_cv_accuracy"]))
    check(
        "Table 6: supervised upper bound",
        close(model["blocked_cv_accuracy_supervised"] * 100.0, 80.9, 0.05)
        and close(model["random_cv_accuracy_supervised"] * 100.0, 97.7, 0.05),
    )
    expected_confusion = [[26, 9, 5, 19], [17, 132, 3, 0], [13, 5, 67, 0], [7, 0, 0, 48]]
    check("Table 6: blocked confusion matrix", model["blocked_confusion_matrix"] == expected_confusion)
    report = model["blocked_classification_report"]
    check("Table 7: Flat recall", close(report["Flat"]["recall"], 0.44, 0.006), str(report["Flat"]["recall"]))
    check("Table 7: Stairs recall", close(report["Stairs"]["recall"], 0.87, 0.006), str(report["Stairs"]["recall"]))
    check("Table 7: Tactile recall", close(report["Tactile"]["recall"], 0.87, 0.006), str(report["Tactile"]["recall"]))


def check_propositions() -> None:
    paper_base = 1.20e-5
    paper_lpf = 46.20e-5
    check("Prop. 3: LPF flat-trace ratio", close(paper_lpf / paper_base, 38.5, 0.05), str(paper_lpf / paper_base))
    check(
        "Prop. 3: flat-trace reduction",
        close((paper_lpf - paper_base) / paper_lpf * 100.0, 97.4, 0.05),
        str((paper_lpf - paper_base) / paper_lpf * 100.0),
    )

    rng = np.random.RandomState(7)
    means = np.array([[0.0, 0.0], [4.0, 0.0], [0.0, 4.0]])
    labels = rng.randint(0, 3, size=90)
    vision = means[labels] + rng.normal(0.0, 0.35, size=(labels.size, 2))
    depth = means[labels] * 0.7 + rng.normal(0.0, 0.45, size=(labels.size, 2))
    qv = rng.uniform(0.45, 0.95, size=labels.size)
    qd = rng.uniform(0.45, 0.95, size=labels.size)
    model = ReliabilityWeightedKMeans(n_clusters=3, beta=4.0, n_init=3, seed=3).fit(vision, depth, qv, qd)
    history = np.asarray(model.history_, dtype=float)
    monotone = bool(np.all(np.diff(history) <= 1e-8 * np.maximum(1.0, np.abs(history[:-1]))))
    check("Prop. 1: monotone RW-MVK objective", monotone, str(history))

    qmin, qmax = 0.1, 0.9
    weight, _ = modality_weights(np.array([qmin]), np.array([qmax]), beta=4.0)
    bound = np.exp(-4.0 * (qmax - qmin))
    check("Prop. 2: exponential attenuation", float(weight[0]) <= float(bound) + 1e-12, f"{weight[0]:.6f} <= {bound:.6f}")
    check(
        "Eq. (5): softmax remains finite at qd = 0",
        modality_weights(np.array([0.5]), np.array([0.0]))[1][0] > 0.0,
    )
    check(
        "Algorithm 2: depth dropout boundary",
        modality_weights(np.array([0.5]), np.array([0.0]), hard_depth_dropout=True)[1][0] == 0.0,
    )


def check_118_artifacts() -> None:
    stats_path = PROJECT_ROOT / "figures" / "meeting118_statistics.json"
    if not stats_path.exists():
        NOTES.append("118 statistics JSON has not been generated yet.")
        return
    stats = json.loads(stats_path.read_text(encoding="utf-8"))
    runtime = {row["operation"]: row["mean_ms"] for row in stats["runtime"]}
    check("118 runtime: health", 0.1 < runtime.get("Health scores (per frame)", 0.0) < 1.0, str(runtime))
    check("118 runtime: readout K=32", runtime.get("Nearest-centroid readout K=32 (per frame)", 1.0) < 1.0)
    check("118 runtime: RW-MVK K=32", runtime.get("RW-MVK calibration K=32, n_init=10 (351 frames)", 1e9) < 1000.0)
    paired = stats["paired_statistics"]
    clean_depth = next(row for row in paired if row["level"] == "clean" and row["baseline"] == "Depth only")
    severe_depth = next(row for row in paired if row["level"] == "severe" and row["baseline"] == "Depth only")
    check("118 stats: clean gain over depth-only significant", clean_depth["p_value"] < 0.05, str(clean_depth["p_value"]))
    check("118 stats: severe depth-only tie reported", severe_depth["p_value"] > 0.05, str(severe_depth["p_value"]))
    curve = stats["calibration_curve"]
    low = next(row for row in curve if abs(row["fraction"] - 0.25) < 1e-6)
    full = next(row for row in curve if abs(row["fraction"] - 1.0) < 1e-6)
    check("118 label efficiency: 25% within 1 pp of 100%", abs(low["cluster_mean"] - full["cluster_mean"]) < 0.01, str((low["cluster_mean"], full["cluster_mean"])))
    for name in (
        "figure7_dataset_atlas.csv",
        "figure7_class_color_codes.csv",
        "figure8_clustering_embeddings.csv",
        "figure8_method_metrics.csv",
        "figure8_per_class_recall.csv",
        "figure9_runtime.csv",
        "figure9_paired_statistics.csv",
        "figure9_calibration_curve.csv",
        "figure9_per_seed_accuracy.csv",
        "figure9_per_class_recall.csv",
    ):
        check(f"118 source data: {name}", (PROJECT_ROOT / "112" / "source_data" / name).exists())


def check_figures(directory: Path) -> None:
    stems = (
        "Figure1_method_roadmap",
        "Figure2_nyu_clustering",
        "Figure3_reliability_sweep",
        "Figure4_sapf_comparison",
        "Figure5_go1_closed_loop",
        "Figure6_go1_scene_and_degradation",
        "Figure7_dataset_atlas",
        "Figure8_clustering_qualitative",
        "Figure9_efficiency_and_statistics",
        "FigureS1_modality_weights",
        "FigureS2_hyperparameter_sensitivity",
        "FigureS3_blocked_cv_confusion",
        "FigureS4_covariance_gating",
    )
    for stem in stems:
        pdf = directory / "pdf" / f"{stem}.pdf"
        png = directory / "png_1000dpi" / f"{stem}_1000dpi.png"
        check(f"Figure file: {stem}.pdf", pdf.exists() and pdf.stat().st_size > 10_000, str(pdf))
        if png.exists():
            with Image.open(png) as image:
                dpi = image.info.get("dpi", (0, 0))
                width, height = image.size
            check(
                f"Figure file: {stem} PNG 1000 dpi",
                abs(float(dpi[0]) - 1000.0) < 1.0 and width >= 6000,
                f"dpi={dpi}, size={width}x{height}",
            )
        else:
            check(f"Figure file: {stem} PNG", False, str(png))

    combined = directory / "112_all_figures.pdf"
    if combined.exists() and shutil.which("pdfinfo") is not None:
        info = subprocess.check_output(["pdfinfo", str(combined)], text=True)
        pages = [line for line in info.splitlines() if line.startswith("Pages:")]
        check("Combined PDF page count", pages and pages[0].split()[-1] == str(len(stems)), str(pages))
    else:
        check("Combined PDF exists", combined.exists(), str(combined))

    archive = directory.parent / f"{directory.name}.zip"
    if archive.exists():
        check("Package archive exists", archive.stat().st_size > 100_000, str(archive))
    else:
        NOTES.append(f"Archive {archive.name} has not been created yet.")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--figures", type=Path, default=PROJECT_ROOT / "112")
    parser.add_argument("--skip-figures", action="store_true")
    arguments = parser.parse_args()

    check_canonical_tables()
    check_figure_source_data()
    check_propositions()
    check_118_artifacts()
    if not arguments.skip_figures:
        check_figures(arguments.figures)

    for note in NOTES:
        print(f"[NOTE] {note}")
    if FAILURES:
        print(f"\n{len(FAILURES)} check(s) failed.")
        for failure in FAILURES:
            print(f"  - {failure}")
        raise SystemExit(1)
    print("\nAll paper-number, proposition, and figure-deliverable checks passed.")


if __name__ == "__main__":
    main()
